// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { loadedLinkCounts, loadedLinksOf, moreLinks } from "../../../main/frontend/graph-explorer/link-counts.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";

const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const uri = (value) => ({ type: "uri", value });
const row = (source, predicate, target) => ({ source, predicate: uri(predicate), target });
const graph = mergeTriples(
  { nodes: [], edges: [], revision: 0 },
  bindingsToTriples([
    row(uri("urn:a"), "urn:p", uri("urn:b")),
    row(uri("urn:c"), "urn:p", uri("urn:a")),
    row(uri("urn:a"), "urn:p", uri("urn:a")),
    row(uri("urn:a"), RDF_TYPE, uri("urn:T")),
    row(uri("urn:a"), "urn:name", { type: "literal", value: "A", "xml:lang": "en" }),
    row(uri("urn:a"), "urn:p", { type: "bnode", value: "x" }),
  ]),
);

test("the loaded links of a node are the canvas's: types and values left out, a self-link counted both ways", () => {
  const counts = loadedLinkCounts(graph);
  assert.equal(counts.get("urn:a"), 5, "b, c, itself twice and the blank node");
  assert.equal(counts.get("urn:b"), 1);
  assert.equal(counts.get("urn:T") ?? 0, 0);
});

test("the statements Expand leaves out are every loaded statement of the node, blank nodes excepted", () => {
  const loaded = loadedLinksOf(graph, ["urn:a"]).get("urn:a");
  assert.deepEqual(
    [...loaded.outgoing].sort(),
    [
      ["<urn:name>", '"A"@en'],
      ["<urn:p>", "<urn:a>"],
      ["<urn:p>", "<urn:b>"],
      [`<${RDF_TYPE}>`, "<urn:T>"],
    ].sort(),
  );
  assert.deepEqual([...loaded.incoming].sort(), [["<urn:a>", "<urn:p>"], ["<urn:c>", "<urn:p>"]].sort());
});

test("more links: what the repository has beyond what is loaded, and a lower bound past the cap", () => {
  assert.deepEqual(moreLinks(12, 5, 999), { count: 7, atLeast: false, text: "+7" });
  assert.equal(moreLinks(5, 5, 999), null);
  assert.equal(moreLinks(3, 5, 999), null, "links loaded from another graph scope");
  assert.deepEqual(moreLinks(1000, 80, 999), { count: 920, atLeast: true, text: "920+" });
});

import { moreLinksPhrase } from "../../../main/frontend/graph-explorer/link-counts.ts";

test("the badge reads as a phrase: one link, several links, at least several links", () => {
  assert.equal(moreLinksPhrase("+1"), "1 more link");
  assert.equal(moreLinksPhrase("+12"), "12 more links");
  assert.equal(moreLinksPhrase("920+"), "at least 920 more links");
});

import { bringsNewLinks, linkCountCap, linkTotalStale } from "../../../main/frontend/graph-explorer/link-counts.ts";

test("link counts go past the links the graph holds, so a hub with 1,000 loaded links still shows more", () => {
  assert.equal(linkCountCap(0, 999), 999);
  assert.equal(linkCountCap(1200, 999), 2199);
  assert.equal(linkCountCap(500000, 999), 100000, "the count query's own bound");
  assert.equal(linkTotalStale(undefined, 0), true, "never counted");
  assert.equal(linkTotalStale({ count: 12, cap: 999 }, 12), false, "an exact count stays");
  assert.equal(linkTotalStale({ count: 1000, cap: 999 }, 80), false, "920+ is still true");
  assert.equal(linkTotalStale({ count: 1000, cap: 999 }, 1000), true, "counted only as far as the loaded links");
  assert.deepEqual(moreLinks(2200, 1200, 2199), { count: 1000, atLeast: true, text: "1000+" });
});

test("an answer brings new links only when one of its statements is not in the graph yet", () => {
  assert.equal(bringsNewLinks(graph, [row(uri("urn:a"), "urn:p", uri("urn:b")), row(uri("urn:c"), "urn:p", uri("urn:a"))]), false);
  assert.equal(bringsNewLinks(graph, [row(uri("urn:a"), "urn:p", uri("urn:b")), row(uri("urn:a"), "urn:p", uri("urn:z"))]), true);
  assert.equal(bringsNewLinks(graph, []), false);
});
